"""Immediate retry wrapper for Meridian integration endpoints."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(
    endpoint_cfg: dict,
    transport: Callable[[str, int], Any],
) -> dict:
    """Invoke transport with the endpoint's legacy retry-count semantics."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    attempt_budget = endpoint_cfg["retry"] + 1

    for attempts in range(1, attempt_budget + 1):
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts == attempt_budget:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }

    raise RuntimeError("retry attempt budget must permit at least one attempt")
